        var sesion = new Sesion(fabrica);
        await sesion.RegistrarTresIdentidades();
        await sesion.PreguntarEn(3, "EST-004");
        var llamadasLlm = fabrica.Llm.Llamadas;

        var registrada = await sesion.PreguntarEn(4, "EST-001");

